tool_input.command:
python3 - <<'EOF'
p='src/board.ts'
s=open(p).read()
i=s.index('export function createBoard')
s=s[:i]+'''interface Card {
  id: string;
  title: string;
  column: number;
  blocked: boolean;
  blockReason: string | null;
  /** Blocked intervals; an open interval has `end === null`. */
  blockedIntervals: { start: number; end: number | null }[];
  startedAt: number | null;
  finishedAt: number | null;
}

export function createBoard(options: BoardOptions): Board {
  const columns = options.columns.map((c) => ({ ...c }));
  const now = options.now;
  const lastIndex = columns.length - 1;
  const cards = new Map<string, Card>();
  const lanes: string[][] = columns.map(() => []);
  let nextId = 1;

  function getCard(cardId: string): Card {
    const card = cards.get(cardId);
    if (!card) throw new BoardError("UNKNOWN_CARD", `Unknown card ${cardId}`);
    return card;
  }

  function columnIndex(name: string): number {
    const index = columns.findIndex((c) => c.name === name);
    if (index < 0) throw new BoardError("UNKNOWN_COLUMN", `Unknown column ${name}`);
    return index;
  }

  function isFull(index: number): boolean {
    const limit = columns[index].wipLimit;
    return limit !== undefined && lanes[index].length >= limit;
  }

  return {
    addCard(title) {
      if (title.trim() === "") throw new BoardError("EMPTY_TITLE", "Title must not be empty");
      if (isFull(0)) throw new BoardError("WIP_LIMIT", `Column ${columns[0].name} is full`);
      const id = `C${nextId++}`;
      cards.set(id, {
        id,
        title,
        column: 0,
        blocked: false,
        blockReason: null,
        blockedIntervals: [],
        startedAt: null,
        finishedAt: null,
      });
      lanes[0].push(id);
      return id;
    },

    move(cardId, toColumn) {
      const card = getCard(cardId);
      const target = columnIndex(toColumn);
      if (target === card.column) throw new BoardError("SAME_COLUMN", `Card ${cardId} is already in ${toColumn}`);
      if (card.blocked) throw new BoardError("BLOCKED", `Card ${cardId} is blocked`);
      if (target > card.column + 1) throw new BoardError("SKIP_NOT_ALLOWED", `Card ${cardId} cannot skip columns`);
      if (isFull(target)) throw new BoardError("WIP_LIMIT", `Column ${toColumn} is full`);

      const t = now();
      const from = lanes[card.column];
      from.splice(from.indexOf(cardId), 1);
      lanes[target].push(cardId);
      if (card.column === 0 && card.startedAt === null) card.startedAt = t;
      if (target === lastIndex) card.finishedAt = t;
      card.column = target;
    },

    block(cardId, reason) {
      const card = getCard(cardId);
      if (card.blocked) throw new BoardError("ALREADY_BLOCKED", `Card ${cardId} is already blocked`);
      card.blocked = true;
      card.blockReason = reason;
      card.blockedIntervals.push({ start: now(), end: null });
    },

    unblock(cardId) {
      const card = getCard(cardId);
      if (!card.blocked) throw new BoardError("NOT_BLOCKED", `Card ${cardId} is not blocked`);
      card.blocked = false;
      card.blockReason = null;
      card.blockedIntervals[card.blockedIntervals.length - 1].end = now();
    },

    cardsIn(column) {
      return [...lanes[columnIndex(column)]];
    },

    cycleTime(cardId) {
      const card = getCard(cardId);
      if (card.column !== lastIndex || card.startedAt === null || card.finishedAt === null) return null;
      const started = card.startedAt;
      const finished = card.finishedAt;
      let blockedMs = 0;
      for (const { start, end } of card.blockedIntervals) {
        // An open interval extends at least to the finish; clipping makes the exact end irrelevant.
        const from = Math.max(start, started);
        const to = Math.min(end ?? finished, finished);
        if (to > from) blockedMs += to - from;
      }
      return { totalMs: finished - started, blockedMs };
    },
  };
}
'''
open(p,'w').write(s)
EOF

python3 - <<'EOF'
p='src/board.test.ts'
s=open(p).read()
i=s.index('test("blocked interval spanning')
s=s[:i]+'''test("blocked time is clipped to the started-finished interval", () => {
  const { board, clock } = setup([{ name: "A" }, { name: "B" }, { name: "C" }]);
  board.addCard("a");
  board.block("C1", "x"); // 1000
  clock.t = 2000;
  board.unblock("C1");
  board.move("C1", "B"); // started 2000
  clock.t = 2500;
  board.block("C1", "y");
  clock.t = 3000;
  board.unblock("C1");
  board.move("C1", "C"); // finished 3000
  board.block("C1", "z"); // still open
  clock.t = 5000;
  expect(board.cycleTime("C1")).toEqual({ totalMs: 1000, blockedMs: 500 });
});
'''
open(p,'w').write(s)
EOF
